// Test shim of the fflate (MIT) calls BumpMesh makes: zipSync, unzipSync,
// strToU8, strFromU8, unzlibSync, on node:zlib. Written from the ZIP
// specification (PKWARE APPNOTE 4.3: local headers, central directory, end
// record; stored and deflated entries), so a Python zipfile project is read
// by an independent reader. bm_js.mjs prefers a real 'fflate' when present.
import zlib from 'node:zlib';

export const strToU8 = (s) => new TextEncoder().encode(s);
export const strFromU8 = (u) => new TextDecoder().decode(u);
export const unzlibSync = (u) => new Uint8Array(zlib.inflateSync(u));

const CRC = new Int32Array(256).map((_, n) => { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; return c; });
function crc32(u) { let c = -1; for (let i = 0; i < u.length; i++) c = CRC[(c ^ u[i]) & 255] ^ (c >>> 8); return (c ^ -1) >>> 0; }

export function zipSync(files) {
  const parts = [], central = [];
  let off = 0;
  for (const [name, data] of Object.entries(files)) {
    const fn = strToU8(name), raw = data instanceof Uint8Array ? data : new Uint8Array(data);
    const comp = new Uint8Array(zlib.deflateRawSync(raw, { level: 6 }));
    const crc = crc32(raw);
    const h = Buffer.alloc(30);
    h.writeUInt32LE(0x04034b50, 0); h.writeUInt16LE(20, 4); h.writeUInt16LE(0x800, 6); h.writeUInt16LE(8, 8);
    h.writeUInt32LE(crc, 14); h.writeUInt32LE(comp.length, 18); h.writeUInt32LE(raw.length, 22); h.writeUInt16LE(fn.length, 26);
    const c = Buffer.alloc(46);
    c.writeUInt32LE(0x02014b50, 0); c.writeUInt16LE(20, 4); c.writeUInt16LE(20, 6); c.writeUInt16LE(0x800, 8); c.writeUInt16LE(8, 10);
    c.writeUInt32LE(crc, 16); c.writeUInt32LE(comp.length, 20); c.writeUInt32LE(raw.length, 24); c.writeUInt16LE(fn.length, 28);
    c.writeUInt32LE(off, 42);
    parts.push(h, fn, comp); central.push(c, fn);
    off += 30 + fn.length + comp.length;
  }
  const cd = Buffer.concat(central);
  const e = Buffer.alloc(22);
  e.writeUInt32LE(0x06054b50, 0); e.writeUInt16LE(central.length / 2, 8); e.writeUInt16LE(central.length / 2, 10);
  e.writeUInt32LE(cd.length, 12); e.writeUInt32LE(off, 16);
  return new Uint8Array(Buffer.concat([...parts, cd, e]));
}

export function unzipSync(u) {
  const b = Buffer.from(u.buffer, u.byteOffset, u.byteLength);
  let e = b.length - 22;
  while (e >= 0 && b.readUInt32LE(e) !== 0x06054b50) e--;
  if (e < 0) throw new Error('invalid zip data');
  const n = b.readUInt16LE(e + 10);
  let p = b.readUInt32LE(e + 16);
  const out = {};
  for (let i = 0; i < n; i++) {
    if (b.readUInt32LE(p) !== 0x02014b50) throw new Error('invalid zip data');
    const method = b.readUInt16LE(p + 10), csize = b.readUInt32LE(p + 20), usize = b.readUInt32LE(p + 24);
    const fl = b.readUInt16LE(p + 28), xl = b.readUInt16LE(p + 30), cl = b.readUInt16LE(p + 32), lo = b.readUInt32LE(p + 42);
    const name = b.toString('utf8', p + 46, p + 46 + fl);
    if (b.readUInt32LE(lo) !== 0x04034b50) throw new Error('invalid zip data');
    const ds = lo + 30 + b.readUInt16LE(lo + 26) + b.readUInt16LE(lo + 28);
    const comp = b.subarray(ds, ds + csize);
    const raw = method === 0 ? comp : method === 8 ? zlib.inflateRawSync(comp) : null;
    if (!raw) throw new Error('unknown compression type ' + method);
    if (raw.length !== usize) throw new Error('invalid zip data');
    out[name] = new Uint8Array(raw);
    p += 46 + fl + xl + cl;
  }
  return out;
}
